Std_ReturnType status = Can_Write(MailboxId, &PduInfo);
if (status != E_OK) {
    Dem_ReportErrorStatus(CAN_WRITE_FAILED_EVENT, DEM_EVENT_STATUS_FAILED);
}

switch (actuator_state) {
    case ACTUATOR_IDLE: HandleIdle(); break;
    case ACTUATOR_ACTIVE: HandleActive(); break;
    default:
        SetLimpHomeMode();
        Dem_ReportErrorStatus(STATE_MACHINE_CORRUPT, DEM_EVENT_STATUS_FAILED);
        break;
}

